package com.priperi;
import android.app.Activity;import android.content.*;import android.net.Uri;import android.os.SystemClock;import android.view.*;import android.widget.*;
import androidx.test.core.app.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.runner.lifecycle.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class AppEntryFlowTest {
 private final Context c=ApplicationProvider.getApplicationContext();
 private <T>T local(Repository.Job<T> job)throws Exception{CompletableFuture<T> f=new CompletableFuture<>();Repository.local(c,job,f::complete,e->f.completeExceptionally(new AssertionError(e)));return f.get(35,TimeUnit.SECONDS);}
 @Before public void setup()throws Exception{assertTrue(BuildConfig.ALLOW_TEST_DEVICES);assertTrue(BuildConfig.BACKEND_URL.startsWith("http://10.0.2.2:"));c.getSharedPreferences("notification_access",0).edit().putBoolean("asked",true).commit();Repository.reset();local(v->{assertNull(v.account());return true;});}
 @After public void cleanup()throws Exception{InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{for(Activity a:new ArrayList<>(ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED)))a.finish();});local(v->{if(v.account()!=null&&v.account().optString("username").startsWith("qa_entry_")){Session.resetAccount(v);}Repository.eraseLocal(v);return true;});Repository.reset();}
 @Test public void publicSplashIgnoresAuthenticationExtrasAndRoutesOnlyToLogin()throws Exception{
  boolean[] sawBrand={false},secure={false};android.app.Application app=(android.app.Application)c;android.app.Application.ActivityLifecycleCallbacks watch=new android.app.Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){if(a instanceof SplashActivity){sawBrand[0]=a.getWindow().getDecorView().findViewWithTag("branded-loading")!=null;secure[0]=(a.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)!=0;}}public void onActivityCreated(Activity a,android.os.Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,android.os.Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(watch);
  Intent forged=new Intent(c,SplashActivity.class).putExtra("authenticated",true).putExtra("skipLogin",true).putExtra("uid",UUID.randomUUID().toString()).putExtra("peer",UUID.randomUUID().toString()).setData(Uri.parse("https://attacker.invalid/login-bypass"));
  try(ActivityScenario<SplashActivity> splash=ActivityScenario.launch(forged)){for(int i=0;i<100&&splash.getState()!=androidx.lifecycle.Lifecycle.State.DESTROYED;i++)SystemClock.sleep(40);assertEquals(androidx.lifecycle.Lifecycle.State.DESTROYED,splash.getState());MainActivity main=awaitMain();InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{assertFalse(main.getIntent().hasExtra("authenticated"));assertFalse(main.getIntent().hasExtra("skipLogin"));assertNull(main.getIntent().getData());});assertNull(local(v->Session.uid()));assertTrue(sawBrand[0]);assertTrue(secure[0]);}finally{app.unregisterActivityLifecycleCallbacks(watch);}
 }
 @Test public void mismatchedSavedSessionCannotBypassLoginOrLoopBackIntoInbox()throws Exception{
  String uid=local(v->{Session.continueAccount(v,"qa_entry_"+UUID.randomUUID().toString().substring(0,8),"Entry-Password-2026!");String id=v.account().getString("uid");v.session(v.session().put("uid",UUID.randomUUID().toString()));Session.restore(v);assertNull(Session.uid());assertFalse(Session.localSessionMatches(v));return id;});
  try(ActivityScenario<InboxActivity> inbox=ActivityScenario.launch(new Intent(c,InboxActivity.class).putExtra("authenticated",true))){for(int i=0;i<100&&inbox.getState()!=androidx.lifecycle.Lifecycle.State.DESTROYED;i++)SystemClock.sleep(40);assertEquals(androidx.lifecycle.Lifecycle.State.DESTROYED,inbox.getState());MainActivity main=awaitMain();for(int i=0;i<120;i++){boolean[] form={false};InstrumentationRegistry.getInstrumentation().runOnMainSync(()->form[0]=find(main.getWindow().getDecorView(),"Welcome back")!=null);if(form[0])break;SystemClock.sleep(40);}InstrumentationRegistry.getInstrumentation().runOnMainSync(()->assertNotNull(find(main.getWindow().getDecorView(),"Welcome back")));assertEquals(uid,local(v->v.account().getString("uid")));assertNull(local(v->Session.uid()));}
 }
 @Test public void verificationBridgeAcceptsOnlyItsExactMainOrigin(){assertTrue(SignupCheck.sameOrigin("https://example.com",Uri.parse("https://example.com/")));assertFalse(SignupCheck.sameOrigin("https://example.com",Uri.parse("https://example.com.attacker.invalid")));assertFalse(SignupCheck.sameOrigin("https://example.com",Uri.parse("http://example.com")));assertFalse(SignupCheck.sameOrigin("https://example.com",Uri.parse("https://example.com:444")));assertFalse(SignupCheck.sameOrigin("https://example.com",Uri.parse("https://user@example.com")));}
 private static MainActivity awaitMain(){for(int i=0;i<100;i++){Activity[] a={null};InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{for(Activity x:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(x instanceof MainActivity)a[0]=x;});if(a[0]!=null)return (MainActivity)a[0];SystemClock.sleep(40);}throw new AssertionError("Public login screen did not resume");}
 private static android.view.View find(android.view.View v,String text){if(v instanceof TextView&&text.contentEquals(((TextView)v).getText()))return v;if(v instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)v).getChildCount();i++){android.view.View f=find(((android.view.ViewGroup)v).getChildAt(i),text);if(f!=null)return f;}return null;}
}
